import{_ as a,a as t,c as r,k as s}from"./chunks/framework.CfBWHN5N.js";const m=JSON.parse('{"title":"Evidence-Governed AI Systems","description":"Explore Keith Williams’s research on tracing AI claims to evidence, sharing scarce review time, and testing which decisions people should keep.","frontmatter":{"title":"Evidence-Governed AI Systems","description":"Explore Keith Williams’s research on tracing AI claims to evidence, sharing scarce review time, and testing which decisions people should keep.","teaser":"Start with a flawed video export, a repeated witness account, or a queue of decisions. Each exposes a different way an AI system can earn a reader’s trust.","articleGenre":"Research collection","dateLabel":"November 2026"},"headers":[],"relativePath":"research/systems/index.md","filePath":"research/systems/index.md"}'),n={name:"research/systems/index.md"};function i(o,e,c,d,h,l){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="evidence-governed-ai-systems" tabindex="-1">Evidence-Governed AI Systems <a class="header-anchor" href="#evidence-governed-ai-systems" aria-label="Permalink to &quot;Evidence-Governed AI Systems&quot;">​</a></h1><p>I want to be able to hand someone a briefing and answer a simple question about any sentence in it. <em>Where did that come from?</em> The hard cases are the ones in which a citation exists but points to another summary, two apparent witnesses turn out to be one, or the reviewer who could settle the matter has fifty other decisions waiting.</p><p>This collection brings together working software, design papers, and proposed experiments. The essays are personal research notes. The linked repositories let you inspect which parts I have built.</p><h2 id="a-connected-research-vision" tabindex="-1">A connected research vision <a class="header-anchor" href="#a-connected-research-vision" aria-label="Permalink to &quot;A connected research vision&quot;">​</a></h2><p>A reader who wants examples can start with <a href="./metavis-evidence-and-evaluation">a video editor’s tests</a>. A researcher interested in evidence can follow <a href="./vision-and-interface">one disputed claim through a proposed interface</a>. For a deliberately difficult dataset, see <a href="./uap-research-testbed">what UAP archives can actually establish</a>.</p><h2 id="the-research-in-one-view" tabindex="-1">The research in one view <a class="header-anchor" href="#the-research-in-one-view" aria-label="Permalink to &quot;The research in one view&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If your question is …</th><th>Start here</th></tr></thead><tbody><tr><td>How do I write a useful task for a coding agent?</td><td><a href="./english-software-engineering">Software requirements an agent can act on</a></td></tr><tr><td>Which decisions deserve an interruption?</td><td><a href="./race-track-pit-stop">Choosing when an AI workflow stops for review</a></td></tr><tr><td>How do I recognize a review bottleneck?</td><td><a href="./human-attention-kanban">Measuring the cost of human attention</a></td></tr><tr><td>How can a reader find the original witness?</td><td><a href="./provenance-knowledge-graphs">Tracing contradictory accounts to their sources</a></td></tr><tr><td>Can one set of evidence support several audiences?</td><td><a href="./personalized-knowledge-artifacts">Personalizing a lesson, report, or briefing</a></td></tr></tbody></table><h2 id="essays-and-technical-case-studies" tabindex="-1">Essays and technical case studies <a class="header-anchor" href="#essays-and-technical-case-studies" aria-label="Permalink to &quot;Essays and technical case studies&quot;">​</a></h2><p>The <a href="./metavis-evidence-and-evaluation">MetaVis engineering case</a> contains code, tests, and hardware notes from a working prototype. The <a href="./vision-and-interface">interface paper</a> shows how a reader might inspect an answer, locate its source, and ask why it changed. The question that connects the two is what a person should be able to verify before accepting an AI-assisted result.</p><h2 id="academic-documents" tabindex="-1">Academic documents <a class="header-anchor" href="#academic-documents" aria-label="Permalink to &quot;Academic documents&quot;">​</a></h2><p>The <a href="./dissertation-proposal">preliminary dissertation proposal</a> sets out potential experiments, comparison methods, and measures. The <a href="./literature-and-faculty">literature and faculty reading map</a> identifies earlier work that informs those choices. Both are discussion documents. The proposal awaits formal academic review.</p><h2 id="implemented-evidence-versus-proposals" tabindex="-1">Implemented evidence versus proposals <a class="header-anchor" href="#implemented-evidence-versus-proposals" aria-label="Permalink to &quot;Implemented evidence versus proposals&quot;">​</a></h2><p><a href="https://github.com/kaw393939/chunky-monkey-text-chunker" target="_blank" rel="noreferrer">Chunky Monkey</a> contains document processing and verification code. <a href="https://github.com/kaw393939/metavis-demo-projects" target="_blank" rel="noreferrer">MetaVis</a> contains a Swift/Metal pipeline and quality checks. A private Ordo Executor prototype implements ingestion and candidate-review contracts.</p><p>The <a href="https://github.com/kaw393939/ordo" target="_blank" rel="noreferrer">Ordo project</a> documents the design for a broader runtime. Its implementation remains planned. In November 2026 the private UAP catalog held 38 metadata records and an acquisition plan. The source collection, labeled benchmark, and evaluation of the combined system are future work. Its reliability, usability, and cost advantages remain open questions.</p>',14)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
